using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "SentinelCustomAnimationData", menuName = "Data/Animation/SentinelCustomAnimationData")]
public class SentinelCustomAnimationData : CustomAnimationData
{
	public override AnimationType GetCustomStartingAnimationType(GameObject gameObject)
	{
		if (gameObject.GetComponent<CompanionInitializer>().CompanionData.CompanionID == "MultiphaseGearTwo")
		{
			return AnimationType.Idle2;
		}
		return AnimationType.Idle;
	}
}
